// Vercel serverless function: online check-in with aircraft-aware seat
// assignment.
//   GET  /api/checkin (Authorization: Bearer <Discord token>)
//        -> { checkins: [{ flightNumber, date, seat, passUrl, aircraft, cabin }] }
//   POST /api/checkin (Authorization: Bearer <Discord token>)
//        body: { flightNumber, date }
//        -> { seat, cabin, passUrl, aircraft } — the boarding pass image is
//           generated by the Emirates boarding-pass service and stored on
//           Vercel Blob so it outlives the generator's ephemeral disk.
//
// Seats are assigned from per-aircraft cabin layouts and never repeat: the
// taken seats for each flight are tracked in a Vercel Blob index, and a
// reserved seat is written back before the pass is issued.
const { put, list } = require('@vercel/blob');

const crypto = require('node:crypto');
const DISCORD_API = process.env.DISCORD_API_BASE || 'https://discord.com/api/v9';
const BLOB_TOKEN = (process.env.BLOB_READ_WRITE_TOKEN || '').trim();

// Boarding-pass images live in the private Blob store; the browser opens
// them through this function with an expiring signature instead of headers.
function signPassUrl(rawUrl) {
    const expires = Date.now() + 7 * 86400000;
    const signature = crypto.createHmac('sha256', BLOB_TOKEN || 'emarates-ice')
        .update(`${rawUrl}|${expires}`).digest('hex').slice(0, 32);
    return `/api/checkin?pass=${encodeURIComponent(rawUrl)}&t=${expires}&s=${signature}`;
}

function passSignatureValid(rawUrl, expires, signature) {
    if (!expires || Date.now() > Number(expires)) return false;
    const expected = crypto.createHmac('sha256', BLOB_TOKEN || 'emarates-ice')
        .update(`${rawUrl}|${expires}`).digest('hex').slice(0, 32);
    return expected === signature;
}
const DISCORD_GUILD_ID = process.env.DISCORD_GUILD_ID || '1294732873143685160';
const DISCORD_BOT_TOKEN = (process.env.DISCORD_BOT_TOKEN || '').trim();
const FIDS_FLIGHTS_URL = process.env.FIDS_FLIGHTS_URL || 'https://emirates-ptfs-fids.onrender.com/api/flights';
const BOARDING_PASS_ENDPOINT = process.env.BOARDING_PASS_ENDPOINT || 'https://emirates-boarding-pass.onrender.com/generate_boarding_pass';
const SEATS_INDEX_PATH = 'checkins/index.json';
const CHECKIN_WINDOW_DAYS = 7;

// Cabin layouts per aircraft family. Rows are continuous through the cabin
// (First at the front), letters differ by cabin geometry. A350 and B737
// have no First cabin in this operation — First passengers there sit in
// the Business zone.
const AIRCRAFT_SEAT_MAPS = {
  A380: {
    First:    { rows: [1, 14], letters: ['A', 'E', 'F'] },
    Business: { rows: [15, 42], letters: ['A', 'C', 'D', 'E', 'F', 'G'] },
    Economy:  { rows: [43, 99], letters: ['A', 'B', 'C', 'D', 'E', 'F', 'G', 'H', 'J', 'K'] }
  },
  B777: {
    First:    { rows: [1, 8], letters: ['A', 'E', 'F'] },
    Business: { rows: [9, 22], letters: ['A', 'C', 'D', 'E', 'F', 'G'] },
    Economy:  { rows: [23, 71], letters: ['A', 'B', 'C', 'D', 'E', 'F', 'G', 'H', 'J', 'K'] }
  },
  A350: {
    Business: { rows: [1, 18], letters: ['A', 'D', 'F', 'G', 'K'] },
    Economy:  { rows: [19, 56], letters: ['A', 'B', 'C', 'D', 'E', 'F'] }
  },
  B737: {
    Business: { rows: [1, 4], letters: ['A', 'C', 'D', 'F'] },
    Economy:  { rows: [5, 30], letters: ['A', 'B', 'C', 'D', 'E', 'F'] }
  }
};

const DEFAULT_SEAT_MAP = {
  Business: { rows: [1, 10], letters: ['A', 'C', 'D', 'F'] },
  Economy:  { rows: [11, 40], letters: ['A', 'B', 'C', 'D', 'E', 'F'] }
};

function json(res, status, body) {
  res.statusCode = status;
  res.setHeader('Content-Type', 'application/json; charset=utf-8');
  res.end(JSON.stringify(body));
}

async function verifyDiscordToken(authorizationHeader) {
  if (!authorizationHeader?.startsWith('Bearer ')) return null;
  try {
    const response = await fetch(`${DISCORD_API}/users/@me`, {
      headers: { Authorization: authorizationHeader },
      signal: AbortSignal.timeout(8000)
    });
    if (!response.ok) return null;
    const profile = await response.json();
    return { id: profile.id, name: profile.global_name || profile.username };
  } catch {
    return null;
  }
}

function discordFetch(path) {
  return fetch(`${DISCORD_API}${path}`, {
    headers: { Authorization: `Bot ${DISCORD_BOT_TOKEN}` },
    signal: AbortSignal.timeout(10000)
  });
}

async function fetchMemberRoleIds(userId) {
  const response = await discordFetch(`/guilds/${DISCORD_GUILD_ID}/members/${userId}`);
  if (!response.ok) return [];
  return (await response.json()).roles || [];
}

function cabinForRoles(roles) {
  const has = (list) => (list || []).some((id) => roles?.includes(id));
  if (has(['1331853227720708146'])) return 'First';
  if (has(['1331852990629417020'])) return 'Business';
  return 'Economy';
}

async function fetchFidsFlights() {
  const response = await fetch(FIDS_FLIGHTS_URL, {
    headers: { Accept: 'application/json' },
    signal: AbortSignal.timeout(45000)
  });
  if (!response.ok) throw new Error(`FIDS responded with ${response.status}`);
  const payload = await response.json();
  return Array.isArray(payload) ? payload : payload.flights || [];
}

function aircraftFamily(aircraft) {
  const value = String(aircraft || '');
  for (const key of Object.keys(AIRCRAFT_SEAT_MAPS)) {
    if (value.toUpperCase().includes(key)) return key;
  }
  return null;
}

function seatMapFor(aircraft, cabin) {
  const family = aircraftFamily(aircraft) || 'B777';
  const map = AIRCRAFT_SEAT_MAPS[family];
  // Cabins the aircraft does not have fall back to the best available zone.
  const order = cabin === 'Charter' || cabin === 'First'
    ? ['First', 'Business']
    : cabin === 'Business' ? ['Business', 'First'] : ['Economy', 'Business'];
  for (const zone of order) {
    if (map[zone]) return { family, cabin: zone, ...map[zone] };
  }
  return { family, cabin: 'Economy', ...DEFAULT_SEAT_MAP.Economy };
}

function seatsInZone(zone) {
  const [from, to] = zone.rows;
  const seats = [];
  for (let row = from; row <= to; row++) {
    for (const letter of zone.letters) seats.push(`${row}${letter}`);
  }
  return seats;
}

async function readSeatIndex() {
  try {
    const { blobs } = await list({ prefix: SEATS_INDEX_PATH, limit: 1 });
    const entry = blobs.find((blob) => blob.pathname === SEATS_INDEX_PATH);
    if (!entry) return {};
    // Private store: the stored URL needs a fresh signed download URL.
    // Private store: reads must carry the blob token.
    const response = await fetch(entry.url, {
      headers: { Authorization: `Bearer ${BLOB_TOKEN}` },
      cache: 'no-store'
    });
    if (!response.ok) return {};
    return await response.json();
  } catch {
    return {};
  }
}

async function writeSeatIndex(index) {
  await put(SEATS_INDEX_PATH, JSON.stringify(index), {
    access: 'private',
    addRandomSuffix: false,
    allowOverwrite: true,
    contentType: 'application/json'
  });
}

async function generateBoardingPass(payload) {
  const response = await fetch(BOARDING_PASS_ENDPOINT, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(payload),
    signal: AbortSignal.timeout(45000)
  });
  if (!response.ok) throw new Error(`The boarding-pass service responded with ${response.status}`);
  return response.json();
}

async function storePassImage(imageUrl, key) {
  const response = await fetch(imageUrl, { signal: AbortSignal.timeout(30000) });
  if (!response.ok) throw new Error(`The generated boarding pass could not be fetched (${response.status})`);
  const buffer = Buffer.from(await response.arrayBuffer());
  const blob = await put(`boarding-passes/${key}.png`, buffer, {
    access: 'private',
    addRandomSuffix: false,
    allowOverwrite: true,
    contentType: 'image/png'
  });
  return blob.url;
}

module.exports = async (req, res) => {
  // Pass proxy: stream a stored boarding-pass image to signed-in members.
  // Private Blob URLs are only readable with the blob token, so the browser
  // goes through this route instead of the store directly.
  const passQuery = req.method === 'GET' && new URL(req.url, 'http://localhost').searchParams.get('pass');
  if (passQuery) {
    const passParams = new URL(req.url, 'http://localhost').searchParams;
    if (!passSignatureValid(passQuery, passParams.get('t'), passParams.get('s'))) {
      res.statusCode = 403;
      res.setHeader('Content-Type', 'application/json');
      return res.end(JSON.stringify({ error: 'This boarding-pass link has expired — reopen your check-in.' }));
    }
    try {
      const response = await fetch(passQuery, {
        headers: { Authorization: `Bearer ${BLOB_TOKEN}` },
        signal: AbortSignal.timeout(15000)
      });
      if (!response.ok) { res.statusCode = response.status; res.setHeader('Content-Type', 'application/json'); return res.end(JSON.stringify({ error: 'That boarding pass is not available.' })); }
      res.statusCode = 200;
      res.setHeader('Content-Type', 'image/png');
      res.setHeader('Cache-Control', 'private, max-age=60');
      const buffer = Buffer.from(await response.arrayBuffer());
      return res.end(buffer);
    } catch (error) {
      res.statusCode = 502;
      res.setHeader('Content-Type', 'application/json');
      return res.end(JSON.stringify({ error: 'The boarding pass could not be loaded.' }));
    }
  }

  if (req.method !== 'GET' && req.method !== 'POST') {
    res.setHeader('Allow', 'GET, POST');
    return json(res, 405, { error: 'Method not allowed.' });
  }

  const pilot = await verifyDiscordToken(req.headers.authorization);
  if (!pilot) return json(res, 401, { error: 'Sign in with Discord to check in.' });

  let body = {};
  if (req.method === 'POST') {
    try {
      body = typeof req.body === 'string' ? JSON.parse(req.body) : req.body;
    } catch {
      return json(res, 400, { error: 'Invalid JSON body.' });
    }
  }

  try {
    const flightNumber = String(body?.flightNumber || '').trim().toUpperCase();
    const flightDate = String(body?.date || '').trim();

    if (req.method === 'GET') {
      // The pilot's own check-ins, newest first.
      const index = await readSeatIndex();
      const mine = [];
      for (const [key, passengers] of Object.entries(index)) {
        for (const entry of passengers) {
          if (String(entry.userId) !== String(pilot.id)) continue;
          const [flightNumber, date] = key.split('|');
          mine.push({
            flightNumber, date,
            seat: entry.seat,
            name: entry.name,
            passUrl: entry.passUrl ? signPassUrl(entry.passUrl) : null,
            aircraft: entry.aircraft,
            cabin: entry.cabin,
            checkedInAt: entry.ts
          });
        }
      }
      mine.sort((a, b) => (b.checkedInAt || 0) - (a.checkedInAt || 0));
      return json(res, 200, { checkins: mine });
    }

    // POST: check in.
    if (!flightNumber || !/^\d{4}-\d{2}-\d{2}$/.test(flightDate)) {
      return json(res, 400, { error: 'A flight number and date (YYYY-MM-DD) are required.' });
    }

    const flights = await fetchFidsFlights();
    const flight = flights.find((entry) =>
      String(entry.flightNumber || '').trim().toUpperCase() === flightNumber &&
      entry.date === flightDate && entry.type === 'departure');
    if (!flight) return json(res, 404, { error: 'That departure is not on the FIDS board.' });
    if (/cancel/i.test(flight.status || '')) {
      return json(res, 409, { error: 'This flight has been cancelled — check-in is closed.' });
    }

    const scheduledStart = Date.parse(`${flight.date}T${flight.departureTime || '00:00'}:00Z`);
    if (Number.isNaN(scheduledStart)) return json(res, 400, { error: 'The flight has no valid departure time.' });
    if (scheduledStart <= Date.now()) {
      return json(res, 409, { error: 'This flight has already departed — check-in is closed.' });
    }
    if (scheduledStart - Date.now() > CHECKIN_WINDOW_DAYS * 86400000) {
      return json(res, 409, { error: `Check-in opens 7 days before departure — this flight departs on ${flight.date}.` });
    }

    const roles = DISCORD_BOT_TOKEN ? await fetchMemberRoleIds(pilot.id) : [];
    const cabin = cabinForRoles(roles);
    const zone = seatMapFor(flight.aircraft, cabin);

    const index = await readSeatIndex();
    const flightKey = `${flightNumber}|${flightDate}`;
    const taken = index[flightKey] || [];
    if (taken.some((entry) => String(entry.userId) === String(pilot.id))) {
      const mine = taken.find((entry) => String(entry.userId) === String(pilot.id));
      return json(res, 409, { error: `You are already checked in — seat ${mine.seat}.`, seat: mine.seat, passUrl: mine.passUrl });
    }

    const takenSeats = new Set(taken.map((entry) => entry.seat));
    const zoneSeats = seatsInZone(zone);
    const seat = zoneSeats.find((candidate) => !takenSeats.has(candidate));
    if (!seat) {
      return json(res, 409, { error: `The ${zone.cabin} cabin on the ${zone.family || flight.aircraft} is full for this flight.` });
    }

    const isDeparture = flight.type === 'departure';
    // Already checked in (e.g. before the boarding-pass storage existed):
    // re-issue the pass for the same seat instead of failing.
    const existingMine = taken.find((entry) => String(entry.userId) === String(pilot.id));
    if (existingMine) {
      const pass = await generateBoardingPass({
        name: pilot.name,
        seat: existingMine.seat,
        departure_code: isDeparture ? 'DXB' : airportCodeOf(flight.destination),
        destination_code: isDeparture ? airportCodeOf(flight.destination) : 'DXB',
        boarding_time: `${flight.departureTime || '00:00'} GMT`,
        class: existingMine.cabin || zone.cabin,
        flight_number: flightNumber,
        departure_name: airportNameOf(isDeparture ? 'DXB' : airportCodeOf(flight.destination), flight),
        destination_name: airportNameOf(isDeparture ? airportCodeOf(flight.destination) : 'DXB', flight)
      });
      const passUrl = await storePassImage(pass.image_url, `${flightNumber}-${flightDate}-${pilot.id}`);
      existingMine.passUrl = passUrl;
      existingMine.ts = Date.now();
      await writeSeatIndex(index);
      return json(res, 200, {
        seat: existingMine.seat,
        cabin: existingMine.cabin || zone.cabin,
        aircraft: flight.aircraft || zone.family,
        passUrl: signPassUrl(passUrl),
        flightNumber,
        date: flightDate,
        departureCode: isDeparture ? 'DXB' : airportCodeOf(flight.destination),
        arrivalCode: isDeparture ? airportCodeOf(flight.destination) : 'DXB',
        reissued: true
      });
    }

    const destinationCode = airportCodeOf(flight.destination);
    const departureCode = isDeparture ? 'DXB' : destinationCode;
    const arrivalCode = isDeparture ? destinationCode : 'DXB';
    const boardingTime = `${flight.departureTime || '00:00'} GMT`;

    const pass = await generateBoardingPass({
      name: pilot.name,
      seat,
      departure_code: departureCode,
      destination_code: arrivalCode,
      boarding_time: boardingTime,
      class: zone.cabin,
      flight_number: flightNumber,
      departure_name: airportNameOf(departureCode, flight),
      destination_name: airportNameOf(arrivalCode, flight)
    });

    const passUrl = await storePassImage(pass.image_url, `${flightNumber}-${flightDate}-${pilot.id}`);
    const record = {
      seat,
      userId: pilot.id,
      name: pilot.name,
      passUrl,
      aircraft: flight.aircraft || zone.family,
      cabin: zone.cabin,
      ts: Date.now()
    };
    index[flightKey] = [...taken, record];
    await writeSeatIndex(index);

    return json(res, 200, {
      seat,
      cabin: zone.cabin,
      aircraft: flight.aircraft || zone.family,
      passUrl: signPassUrl(passUrl),
      flightNumber,
      date: flightDate,
      departureCode,
      arrivalCode
    });
  } catch (error) {
    console.error(`${req.method} /api/checkin failed:`, error);
    if (error.name === 'AbortError' || /aborted|timeout/i.test(error.message || '')) {
      return json(res, 503, { error: 'One of the flight services is waking up (the host sleeps when idle) — try again in a minute.' });
    }
    if (error.code === 'DB_NOT_CONFIGURED' || /DATABASE_URL/.test(error.message || '')) {
      return json(res, 503, { error: 'The miles service is not configured yet.' });
    }
    return json(res, 502, { error: `Check-in could not complete: ${error.message || 'unknown error'}` });
  }
};

function airportCodeOf(destination) {
  return String(destination || '').toUpperCase().match(/\(([A-Z]{3})\)\s*$/)?.[1] || 'DXB';
}

const AIRPORT_NAMES = {
  DXB: 'Dubai International Airport', LHR: 'London Heathrow Airport',
  SYD: 'Kingsford Smith Airport, Sydney', HND: 'Tokyo Haneda Airport',
  SIN: 'Singapore Changi Airport', BOM: 'Chhatrapati Shivaji Maharaj International Airport',
  PER: 'Perth Airport', DOH: 'Hamad International Airport', JFK: 'John F. Kennedy International Airport',
  FCO: 'Leonardo da Vinci Fiumicino Airport', MUC: 'Munich Airport', CDG: 'Paris Charles de Gaulle Airport'
};

function airportNameOf(code, flight) {
  if (!code) return 'Dubai';
  if (code === 'DXB') return 'Dubai';
  return `${AIRPORT_NAMES[code] || code} (${code})`;
}
